import type { HighlighterCore } from 'shiki/core'
import type { LanguageRegistration, ThemedToken } from 'shiki'
import { CODE_THEME, CODE_THEME_NAME } from '../constants/code-theme'
import { escapeHtml } from './html'

/**
 * Code blocks are highlighted on demand: neither the engine nor a grammar is
 * part of the initial bundle, and only the languages a quiz actually uses are
 * fetched. The output is generated by the library from escaped text, with our
 * theme, and is injected after the Markdown has been sanitized.
 */

type LanguageModule = { default: LanguageRegistration | LanguageRegistration[] }

/** The grammars we ship. A new language is one import and one alias. */
const LANGUAGE_LOADERS: Record<string, () => Promise<LanguageModule>> = {
  javascript: () => import('@shikijs/langs/javascript'),
  typescript: () => import('@shikijs/langs/typescript'),
  jsx: () => import('@shikijs/langs/jsx'),
  tsx: () => import('@shikijs/langs/tsx'),
  json: () => import('@shikijs/langs/json'),
  html: () => import('@shikijs/langs/html'),
  css: () => import('@shikijs/langs/css'),
  bash: () => import('@shikijs/langs/bash'),
  python: () => import('@shikijs/langs/python'),
  java: () => import('@shikijs/langs/java'),
}

/** The fence names an author is likely to type, and the grammar they mean. */
const LANGUAGE_ALIASES: Record<string, string> = {
  js: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  ts: 'typescript',
  mts: 'typescript',
  cts: 'typescript',
  py: 'python',
  sh: 'bash',
  shell: 'bash',
  zsh: 'bash',
  htm: 'html',
}

/** The Shiki language a fence asked for, or `undefined` when we do not ship it. */
export function languageIdFor(fence: string | undefined): string | undefined {
  const first = fence?.trim().toLowerCase().split(/\s+/)[0]
  if (!first) return undefined
  const id = LANGUAGE_ALIASES[first] ?? first
  return id in LANGUAGE_LOADERS ? id : undefined
}

const FONT_STYLES: ReadonlyArray<readonly [number, string]> = [
  [1, 'font-style:italic'],
  [2, 'font-weight:700'],
  [4, 'text-decoration:underline'],
]

/** Turn Shiki tokens into spans; the content is escaped, the colour is ours. */
export function tokensToHtml(lines: ThemedToken[][]): string {
  return lines
    .map((line) =>
      line
        .map((token) => {
          const declarations = [`color:${token.color ?? 'inherit'}`]
          for (const [bit, declaration] of FONT_STYLES) {
            if ((token.fontStyle ?? 0) & bit) declarations.push(declaration)
          }
          return `<span style="${declarations.join(';')}">${escapeHtml(token.content)}</span>`
        })
        .join(''),
    )
    .join('\n')
}

let highlighterPromise: Promise<HighlighterCore> | null = null
const loadedLanguages = new Set<string>()

async function getHighlighter(): Promise<HighlighterCore> {
  highlighterPromise ??= (async () => {
    const [{ createHighlighterCore }, { createJavaScriptRegexEngine }] = await Promise.all([
      import('shiki/core'),
      import('shiki/engine/javascript'),
    ])
    return createHighlighterCore({
      themes: [CODE_THEME],
      langs: [],
      engine: createJavaScriptRegexEngine(),
    })
  })()
  return highlighterPromise
}

async function ensureLanguage(instance: HighlighterCore, language: string): Promise<void> {
  if (loadedLanguages.has(language)) return
  const load = LANGUAGE_LOADERS[language]
  if (!load) return
  const module = await load()
  await instance.loadLanguage(module.default)
  loadedLanguages.add(language)
}

/**
 * Highlight one fenced block. Returns `null` when the fence names no language we
 * ship, or when loading the grammar fails: the caller keeps the plain code.
 */
export async function highlightCode(
  source: string,
  fence: string | undefined,
): Promise<string | null> {
  const language = languageIdFor(fence)
  if (!language) return null

  try {
    const instance = await getHighlighter()
    await ensureLanguage(instance, language)
    const { tokens } = instance.codeToTokens(source, {
      lang: language,
      theme: CODE_THEME_NAME,
    })
    return tokensToHtml(tokens)
  } catch {
    return null
  }
}
